  <header class="topbar"><div class="brand"><span class="brand-mark">◇</span><div><h1>符文戰線</h1><span>RUNE CIRCUIT</span></div></div><div class="match-meta"><i class="live-dot"></i><span id="difficulty-label">標準對局</span><span class="meta-divider">/</span><time id="timer">00:00</time></div><nav><button id="help-button" class="icon-button">操作說明 <kbd>?</kbd></button><button id="pause-button" class="icon-button">暫停 <kbd>Esc</kbd></button><button id="sound-button" class="icon-button" aria-label="音量設定">音效</button></nav></header>
